11	namespace gem5
12	{
13	    CHAOSCache::CHAOSCache(const CHAOSCacheParams& p) :
14	        SimObject(p),
15	        targetCache(p.target_cache),
16	        probability(p.probability),
17	        bits_to_change(p.bitsToChange),
18	        corruption_size(p.corruptionSize),
19	        first_clock(p.firstClock),
20	        last_clock(p.lastClock),
21	        fault_type_enum(stringToFaultType(p.faultType)),
22	        fault_mask(static_cast<unsigned char>(std::stoi(p.faultMask, nullptr, 2))),
23	        tick_to_clock_ratio(p.tickToClockRatio),
24	        bit_flip_prob(p.bitFlipProb),
25	        stuck_at_zero_prob(p.stuckAtZeroProb),
26	        stuck_at_one_prob(p.stuckAtOneProb),
27	        cycles_permament_fault_check(p.cyclesPermamentFaultCheck),
28	        write_log(p.writeLog),
29	        target_block_addr(p.targetBlockAddr),
30	        target_byte_offset(p.targetByteOffset),
31	        paired_sector(p.pairedSector),
32	        rng_seed(p.rngSeed),
33	        max_faults(p.maxFaults),
34	        faults_injected_count(0),
35	        attackEvent([this] { this->injectFault(); }, name()),
36	        periodicCheck([this] { this->checkPermanent(); }, name() + ".periodicCheck"),
37	        stats(nullptr)
38	    {
39	        if (probability != 0.0) {
40	            log_stream = simout.create("cache_injections.log", false, true);
41	            if (!log_stream || !log_stream->stream()) {
42	                panic("CHAOSCache: Could not open log file");
43	            }
44	
45	            if (bits_to_change == -1){
46	                std::uniform_int_distribution<int> dist(1, 8);
47	                bits_to_change = dist(rng);
48	            }
49	
50	            stats = std::make_unique<CHAOSCacheStats>(this);
51	
52	            first_tick = first_clock * tick_to_clock_ratio;
53	            last_tick = last_clock * tick_to_clock_ratio;
54	            ticks_permament_fault_check = cycles_permament_fault_check * tick_to_clock_ratio;
55	
56	            rng.seed(rng_seed != 0 ? rng_seed : rd());
57	            inter_fault_cycles_dist = std::geometric_distribution<unsigned>(probability);
58	
59	            scheduleAttack(first_tick + inter_fault_cycles_dist(rng) * tick_to_clock_ratio);
60	
61	            if ((bit_flip_prob + stuck_at_zero_prob + stuck_at_one_prob) != 1.0){
62	                warn("Sum of probabilities is not 1, assuming 0.9 for bitFlipProb, 0.05 for stuckAtZeroProb and 0.05 for stuckAtOneProb.\n");
63	                bit_flip_prob = 0.9;
64	                stuck_at_zero_prob = 0.05;
65	                stuck_at_one_prob = 0.05;
66	            }
67	
68	            std::vector<double> weights = {bit_flip_prob, stuck_at_zero_prob, stuck_at_one_prob};
69	            random_fault_distribution = std::discrete_distribution<int>(weights.begin(), weights.end());
70	
71	            scheduleCheckPermanentFault(first_tick + ticks_permament_fault_check);
72	        }
73	    }
74	
75	    CHAOSCache::CHAOSCacheStats::CHAOSCacheStats(statistics::Group *parent)
76	    : statistics::Group(parent),
77	      ADD_STAT(numFaultsInjected, statistics::units::Count::get(),
78	               "Total number of faults injected"),
79	      ADD_STAT(numBitFlips, statistics::units::Count::get(),
80	               "Number of bit flip faults injected"),
81	      ADD_STAT(numStuckAtZero, statistics::units::Count::get(),
82	               "Number of stuck-at-0 faults injected"),
83	      ADD_STAT(numStuckAtOne, statistics::units::Count::get(),
84	               "Number of stuck-at-1 faults injected"),
85	      ADD_STAT(numPermanentFaults, statistics::units::Count::get(),
86	               "Total number of permanent faults injected")
87	    {
88	    }
89	
90	    CHAOSCache::FaultType 
91	    CHAOSCache::stringToFaultType(const std::string &s) {
92	        if (s == "bit_flip") return FaultType::BitFlip;
93	        else if (s == "stuck_at_zero") return FaultType::StuckAtZero;
94	        else if (s == "stuck_at_one") return FaultType::StuckAtOne;
95	        return FaultType::Random;
