        if (bits == 1) {
            if (data) {  // undo (Corrected)
                switch (ft) {
                    case FaultType::BitFlip:  data[byteOffset] ^= mask; break;
                    case FaultType::StuckAtZero: data[byteOffset] |= mask; break;
                    case FaultType::StuckAtOne:  data[byteOffset] &= ~mask; break;
                    default: break;
                }
