            outcome = ProtectionOutcome::Corrected;
        } else if (bits == 2) {
            if (blk) blk->invalidate();  // DetectedContained (recovery)
            outcome = ProtectionOutcome::DetectedContained;
        } else {
            outcome = ProtectionOutcome::SilentEscape;  // false-hit
        }
