201	        // the old dist spanned [start, end-1] = excluded the final byte.
202	        std::uniform_int_distribution<Addr> dist(target_start, target_end);
203	        Addr target_addr = dist(rng);
204	
205	        try {
206	            // Attack a single byte
207	            uint8_t data;
208	            RequestPtr req = std::make_shared<Request>(target_addr, sizeof(data), 0, 0);
209	            PacketPtr read_pkt = new Packet(req, MemCmd::ReadReq);
210	            read_pkt->dataStatic(&data);
211	
212	            memory->access(read_pkt);
213	
214	            // G5: capture the OLD value (before injection) for the evidence log.
215	            uint8_t old_value = data;
216	
217	            unsigned char mask = (fault_mask != 0) ? fault_mask : generateRandomMask(rng, num_bits_to_change, sizeof(data) << 3);
218	
219	            FaultType chosen_fault_type_enum = fault_type_enum;
220	            if (fault_type_enum == FaultType::Random) {
221	                int faultIdx = random_fault_distribution(rng);
222	                chosen_fault_type_enum = static_cast<FaultType>(faultIdx);
223	            }
224	
225	            switch (chosen_fault_type_enum) {
226	                case FaultType::StuckAtZero:
227	                    data &= ~mask;
228	                    stats->numStuckAtZero++;
229	                    stats->numPermanentFaults++;
230	                    permanent_faults[target_addr] = {chosen_fault_type_enum, mask, true};
231	                    break;
232	                case FaultType::StuckAtOne:
233	                    data |= mask;
234	                    stats->numStuckAtOne++;
235	                    stats->numPermanentFaults++;
236	                    permanent_faults[target_addr] = {chosen_fault_type_enum, mask, true};
237	                    break;
238	                case FaultType::BitFlip:
239	                    data ^= mask;
240	                    stats->numBitFlips++;
241	                    break;
242	                default:
243	                    break;
244	            }
245	
246	            PacketPtr write_pkt = new Packet(req, MemCmd::WriteReq);
247	            write_pkt->dataStatic(&data);
248	
249	            memory->access(write_pkt);
250	            stats->numFaultsInjected++;
251	            ++faults_injected_count;   // G5: count this valid injection
252	
253	            delete read_pkt;
254	            delete write_pkt;
255	
256	            if (write_log){
257	                // G5: evidence log — old/new value + width + mask + type +
258	                // target identity + trigger (tick) + seed (recorded at ctor,
259	                // echoed here for traceability) + faults_injected count.
