72	    CHAOSROB::maybeCorrupt(ThreadID tid, o3::DynInstPtr &head_inst)
73	    {
74	        if (!cpu || probability <= 0.0f) return false;
75	        if (max_faults != 0 && faults_injected_count >= max_faults) return false;
76	        if (!inWindow()) return false;
77	
78	        std::uniform_real_distribution<float> pd(0.0f, 1.0f);
79	        if (pd(rng) > probability) return false;
80	
81	        auto *o3cpu = dynamic_cast<o3::CPU *>(cpu);
82	        if (!o3cpu) return false;
83	
84	        if (fi_mode == Mode::ExcSuppress) {
85	            // §2.3 exc_suppress: clear the head's fault -> a pending
86	            // SError/DUE is silently swallowed (DUE->SDC conversion).
87	            Fault &fref = head_inst->getFault();
88	            Fault old = fref;
89	            fref = NoFault;
90	            faults_injected_count++;
91	            if (write_log) {
92	                *(log_stream->stream()) << "Tick: " << curTick()
93	                    << ", Site: rob_retireHead, mode=exc_suppress, tid=" << (int)tid
94	                    << ", head_sn=" << head_inst->seqNum
95	                    << ", cleared_fault=" << (old ? "yes" : "none")
96	                    << ", faults_injected: " << faults_injected_count
97	                    << std::endl;
98	            }
99	            return true;
100	        } else if (fi_mode == Mode::EntryBitflip) {
101	            // §2.3 entry_bitflip: flip a field of the entry at distance D
102	            // from head. exc_status/done: toggle CanCommit (clear => the
103	            // instruction can't commit -> stall/Crash; set => re-enable).
104	            int D = distance_from_head;
105	            if (D < 0) D = (int)(rng() % 4);
106	            o3::DynInstPtr target = o3cpu->rob.getEntryAtDistance(tid, D);
107	            if (!target) {
108	                if (write_log) {
109	                    *(log_stream->stream()) << "Tick: " << curTick()
110	                        << ", Site: rob_retireHead, mode=entry_bitflip"
111	                        << " — NO entry at D=" << D << " (skipped)." << std::endl;
112	                }
113	                return false;
114	            }
115	            // toggle CanCommit on the target (the done/exc_status proxy).
116	            if (target->readyToCommit()) target->clearCanCommit();
117	            else                          target->setCanCommit();
118	            faults_injected_count++;
119	            if (write_log) {
120	                *(log_stream->stream()) << "Tick: " << curTick()
121	                    << ", Site: rob_retireHead, mode=entry_bitflip"
122	                    << ", field=" << (field == Field::ExcStatus ? "exc_status" : "done")
123	                    << ", tid=" << (int)tid << ", D=" << D
124	                    << ", target_sn=" << target->seqNum
125	                    << ", faults_injected: " << faults_injected_count
126	                    << std::endl;
127	            }
128	            return true;
129	        }
130	        return false;
131	    }
132	
133	    // spec_leak (method1 speculative-state-leak) is DEFERRED — needs the
134	    // squash path edit (don't roll back a wrong-path µop's phys-reg write).
135	    // §2.3 patch 2.
136	
