if (ecc_logic_fault) {
    try {
        uint8_t data8[8];
        RequestPtr req8 = std::make_shared<Request>(target_addr, 8, 0, 0);
        PacketPtr rp = new Packet(req8, MemCmd::ReadReq);
        rp->dataStatic(data8);
        memory->access(rp);
