class CHAOSCache : public SimObject
{
  public:
    CHAOSCache(const CHAOSCacheParams& params);
    virtual ~CHAOSCache() {}

  private:
    enum class FaultType {
      BitFlip,
      StuckAtZero,
      StuckAtOne,
      Random
    };

    struct PermanentFault {
      FaultType fault_type;
      uint64_t mask;
      bool update;
    };

