{

// §2.15 CHAOSNoC forward decl (raw pointer member below).
class CHAOSNoC;

namespace ruby
{

namespace garnet
{

class GarnetNetwork;

class NetworkLink : public ClockedObject, public Consumer
{
  public:
    typedef NetworkLinkParams Params;
    NetworkLink(const Params &p);
    ~NetworkLink() = default;

    void setLinkConsumer(Consumer *consumer);
    void setSourceQueue(flitBuffer *src_queue, ClockedObject *srcClockObject);
    virtual void setVcsPerVnet(uint32_t consumerVcs);
    void setType(link_type type) { m_type = type; }
    link_type getType() { return m_type; }
    void print(std::ostream& out) const {}
    int get_id() const { return m_id; }
    flitBuffer *getBuffer() { return &linkBuffer;}
    virtual void wakeup();

    // §2.15 CHAOSNoC: raw pointer to the NoC fault injector. Set by a Ruby
    // config script (configs/se/ruby_chaos.py, deferred). nullptr = no
    // injection (zero regression). wakeup() calls maybeCorrupt(flit).
    CHAOSNoC *chaosNoC = nullptr;
    void setChaosNoC(CHAOSNoC *p) { chaosNoC = p; }

    unsigned int getLinkUtilization() const { return m_link_utilized; }
    const std::vector<unsigned int> & getVcLoad() const { return m_vc_load; }

    inline bool isReady(Tick curTime)
    {
        return linkBuffer.isReady(curTime);
    }

    inline flit* peekLink() { return linkBuffer.peekTopFlit(); }
    inline flit* consumeLink() { return linkBuffer.getTopFlit(); }

    bool functionalRead(Packet *pkt, WriteMask &mask);
    uint32_t functionalWrite(Packet *);
    void resetStats();

    std::vector<int> mVnets;
    uint32_t bitWidth;

  private:
    const int m_id;
    link_type m_type;
    const Cycles m_latency;

    ClockedObject *src_object;

    // Statistical variables
    unsigned int m_link_utilized;
    std::vector<unsigned int> m_vc_load;

  protected:
    uint32_t m_virt_nets;
    flitBuffer linkBuffer;
    Consumer *link_consumer;
    flitBuffer *link_srcQueue;

};

} // namespace garnet
} // namespace ruby
} // namespace gem5

#endif // __MEM_RUBY_NETWORK_GARNET_0_NETWORKLINK_HH__

