cd /home/sdc/gem5-fi
echo "===fp_fwd_kernel 是预编译 binary，没有 .c 源码。输出 'iters=500 fails=N' 不是 16-hex==="
echo "===需写一个有 16-hex checksum 的 store→load 转发 kernel==="
cat > workloads/directed/fwd_checksum_kernel.c << 'EOF'
/* fwd_checksum_kernel — §2.4 LSQFwd 验证 kernel (store→load 转发 + 16-hex checksum)
 *
 * 做 store→load 转发（store 一个 double 到 buffer，立即 load 同地址），
 * FNV-1a 折叠到 16-hex checksum。CHAOSLSQFwd 注入转发数据→位谱。
 *
 * Build: gcc -static -O0 -o fwd_checksum_kernel fwd_checksum_kernel.c -lm
 */
#include <stdio.h>
#include <stdint.h>
#include <string.h>

static uint64_t cs = 0xcbf29ce484222325ULL;
static void fold(const void *p, int n) {
    uint64_t v = 0;
    memcpy(&v, p, n > 8 ? 8 : n);
    cs ^= v; cs *= 0x100000001b3ULL;
}

int main(void) {
    /* store→load forwarding: store a double, immediately load same addr */
    double buf[64];
    for (int i = 0; i < 64; i++) {
        double val = (double)(i * 7 + 3) / 2.0;
        buf[i] = val;              /* store */
        double loaded = buf[i];    /* load same addr → forwarded from store buffer */
        fold(&loaded, sizeof(loaded));
    }
    printf("%016llx\n", cs);
    return 0;
}
EOF
gcc -static -O0 -o fwd_checksum_kernel fwd_checksum_kernel.c -lm && echo "built"
