110	                        << ", Site: rob_retireHead, mode=entry_bitflip"
111	                        << " — NO entry at D=" << D << " (skipped)." << std::endl;
112	                }
113	                return false;
114	            }
115	            // toggle CanCommit on the target (the done/exc_status proxy).
116	            if (target->readyToCommit()) target->clearCanCommit();
117	            else                          target->setCanCommit();
118	            faults_injected_count++;
119	            if (write_log) {
120	                *(log_stream->stream()) << "Tick: " << curTick()
121	                    << ", Site: rob_retireHead, mode=entry_bitflip"
122	                    << ", field=" << (field == Field::ExcStatus ? "exc_status" : "done")
123	                    << ", tid=" << (int)tid << ", D=" << D
124	                    << ", target_sn=" << target->seqNum
125	                    << ", faults_injected: " << faults_injected_count
126	                    << std::endl;
127	            }
128	            return true;
129	        }
130	        return false;
131	    }
